// Runnable demo: a thread-safe template stand-in + concurrency mapping model.
package com.bank.settlement.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SpringKafkaDemo {

    private static final Logger log = Logger.getLogger("SpringKafka");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        int partitionCount = 4;
        TxnEventPublisher publisher = new TxnEventPublisher(partitionCount);

        // Publish keyed events; key = accountId decides the partition.
        List<TxnEvent> events = List.of(
            new TxnEvent("TXN-1", "SAV2001", new BigDecimal("20000")),
            new TxnEvent("TXN-2", "SAV2001", new BigDecimal("30000")),
            new TxnEvent("TXN-3", "CUR3001", new BigDecimal("50000")),
            new TxnEvent("TXN-4", "CUR3001", new BigDecimal("60000"))
        );
        for (TxnEvent e : events) publisher.send("txn.events", e.accountId, e);

        log.info("=== concurrency=2 over 4 partitions: each thread owns 2 ===");
        new ListenerContainerSimulator(2, partitionCount).assign();

        log.info("=== concurrency=5 over 4 partitions: 1 thread stays idle ===");
        new ListenerContainerSimulator(5, partitionCount).assign();
    }
}

