class TxnEvent {
    final String txnId;
    final String accountId;
    final BigDecimal amount;
    TxnEvent(String txnId, String accountId, BigDecimal amount) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
    }
}

// ─── Would be in TxnEventPublisher.java ───
// Models KafkaTemplate: one shared thread-safe sender, send() returns a future.
class TxnEventPublisher {
    private static final Logger log = Logger.getLogger("SpringKafka");
    private final int partitionCount;
    TxnEventPublisher(int partitionCount) { this.partitionCount = partitionCount; }

    CompletableFuture<Integer> send(String topic, String key, TxnEvent event) {
        // Same partitioning rule Kafka uses: hash(key) % partitionCount.
        int partition = Math.floorMod(key.hashCode(), partitionCount);
        return CompletableFuture.supplyAsync(() -> partition)
            .whenComplete((p, ex) -> {
                if (ex == null) {
                    log.info(() -> "sent topic=" + topic + " key=" + key
                            + " txn=" + event.txnId + " -> partition=" + p);
                } else {
                    log.log(Level.SEVERE, "send failed for " + event.txnId, ex);
                }
            });
    }
}

// ─── Would be in ListenerContainerSimulator.java ───
// Models ConcurrentKafkaListenerContainerFactory.concurrency mapping.
class ListenerContainerSimulator {
    private static final Logger log = Logger.getLogger("SpringKafka");
    private final int concurrency;
    private final int partitionCount;
    ListenerContainerSimulator(int concurrency, int partitionCount) {
        this.concurrency = concurrency;
        this.partitionCount = partitionCount;
    }

    void assign() {
        // One partition is owned by exactly one consumer thread at a time.
        List<List<Integer>> threads = new ArrayList<>();
        for (int i = 0; i < concurrency; i++) threads.add(new ArrayList<>());
        for (int p = 0; p < partitionCount; p++) {
            threads.get(p % concurrency).add(p);
        }
        for (int i = 0; i < concurrency; i++) {
            final int idx = i;
            List<Integer> owned = threads.get(i);
            if (owned.isEmpty()) {
                log.warning(() -> "consumer-thread-" + idx + " IDLE (no partition to own)");
            } else {
                log.info(() -> "consumer-thread-" + idx + " owns partitions " + owned);
            }
        }
    }
}

